<script setup lang="ts">
import Icon from '../../shared/Icon.vue';import {useRoute,useRouter} from 'vue-router';const route=useRoute(),router=useRouter();import {stateLabels} from './workbench-types';
defineProps<{title:string;description:string;counts:Record<string,number>;total:number|null;loading:boolean;error:string;query:string;state:string;nextCursor?:string|null;hasCursor?:boolean;states:string[]}>();
const emit=defineEmits<{'update:query':[value:string];search:[];filter:[state:string];refresh:[];next:[];first:[]}>();
</script>
<template><section class="governance-module"><header class="module-heading"><div><h2>{{title}}</h2><p>{{description}}</p></div><div class="module-actions"><slot name="actions"/></div></header><div class="gov-summary"><div><span>全部记录</span><strong>{{loading||error?'—':counts.ALL??0}}</strong></div><div v-for="key in states.slice(0,3)" :key="key"><span>{{stateLabels[key]??key}}</span><strong>{{loading||error?'—':counts[key]??0}}</strong></div></div><div class="gov-list card"><div class="gov-toolbar"><form class="gov-search" @submit.prevent="emit('search')"><Icon name="search"/><input :value="query" :aria-label="'搜索'+title" placeholder="搜索名称或关键字" maxlength="100" @input="emit('update:query',($event.target as HTMLInputElement).value)"/><button class="btn sm" :disabled="loading" type="submit">搜索</button></form><slot name="filters"/><button class="btn sm" :disabled="loading" aria-label="刷新当前列表" @click="emit('refresh')"><Icon name="refresh"/>刷新</button></div><div class="gov-status-tabs" aria-label="状态筛选"><button :class="{active:!state}" @click="emit('filter','')">全部 <span>{{loading||error?'—':counts.ALL??0}}</span></button><button v-for="key in states" :key="key" :class="{active:state===key}" @click="emit('filter',key)">{{stateLabels[key]??key}} <span>{{loading||error?'—':counts[key]??0}}</span></button></div><p v-if="error" class="banner error" role="alert">{{error}}<button class="btn sm" @click="emit('refresh')">重试读取</button></p><div v-else-if="loading" class="gov-loading" role="status"><span class="gov-spinner"></span>正在核实当前记录…</div><slot v-else/><footer class="gov-pagination"><select class="select" aria-label="每页记录数" :value="route.query.limit==='50'?'50':'20'" :disabled="loading" @change="router.replace({query:{...route.query,limit:($event.target as HTMLSelectElement).value,cursor:undefined}})"><option value="20">20 条 / 页</option><option value="50">50 条 / 页</option></select><span>{{error?'当前记录暂不可用':loading?'正在读取':`共 ${total??0} 条 · 每页 ${route.query.limit==='50'?50:20} 条`}}</span><div><button v-if="hasCursor" class="btn sm" :disabled="loading" @click="emit('first')">返回第一页</button><button class="btn sm" :disabled="loading||!nextCursor" @click="emit('next')">下一页<Icon name="arrowR"/></button></div></footer></div></section></template>
